public class InnerHarnessHarnessAgentCoreRuntimeEnvironmentFactory(Action<Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment>
{

    internal InnerHarnessLifecycleConfigurationFactory LifecycleConfigurationFactory { get; set; }

    internal InnerHarnessNetworkConfigurationFactory NetworkConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment Create()
    {
        var harnessAgentCoreRuntimeEnvironmentResult = CreateHarnessAgentCoreRuntimeEnvironment();
        factoryAction?.Invoke(harnessAgentCoreRuntimeEnvironmentResult);

        return harnessAgentCoreRuntimeEnvironmentResult;
    }

    private Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment CreateHarnessAgentCoreRuntimeEnvironment()
    {
        var harnessAgentCoreRuntimeEnvironmentResult = new Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment();

        return harnessAgentCoreRuntimeEnvironmentResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.HarnessTypes.HarnessAgentCoreRuntimeEnvironment result)
    {
        base.CreateChildren(result);

        result.LifecycleConfiguration ??= LifecycleConfigurationFactory?.Build();
        result.NetworkConfiguration ??= NetworkConfigurationFactory?.Build();
    }

} // End Of Class

